	@Test
	void externalObjectBindingSelectsDescribeSubjectWithoutRestrictingGeneratedLookups() {
		try (Fixture fixture = new Fixture(2)) {
			try (var connection = fixture.federation.getConnection()) {
				GraphQuery query = connection.prepareGraphQuery(DIRECT_DESCRIBE_QUERY);
				query.setBinding("object", Values.literal("Alice"));

				try (GraphQueryResult result = query.evaluate()) {
					var described = QueryResults.asModel(result);

					assertTrue(described.contains(ALICE, RDFS.LABEL, Values.literal("Alice")));
					assertTrue(described.contains(ALICE, RDF.TYPE, FOAF.PERSON),
							"DESCRIBE lookups must not inherit the WHERE binding named object");
					assertFalse(described.contains(BOB, RDF.TYPE, FOAF.PERSON),
							"the WHERE binding must still determine which resources are described");
				}
			}
		}
	}

	@Test
	void nestedWhereBindingSelectsSubjectAndDescriptionIncludesRecursiveAndIncomingStatements() {
		try (Fixture fixture = new Fixture(2)) {
			try (var connection = fixture.federation.getConnection()) {
				GraphQuery query = connection.prepareGraphQuery(DESCRIBE_QUERY);
				query.setBinding("object", Values.literal("Alice"));

				try (GraphQueryResult result = query.evaluate()) {
					var described = QueryResults.asModel(result);

					assertTrue(described.contains(ALICE, RDFS.LABEL, Values.literal("Alice")));
					assertTrue(described.contains(ALICE, RDF.TYPE, FOAF.PERSON),
							"DESCRIBE lookups must not inherit the WHERE binding named object");
					assertFalse(described.contains(BOB, RDF.TYPE, FOAF.PERSON),
							"the WHERE binding must still determine which resources are described");
					assertTrue(described.contains(ALICE, RELATED, null),
							"the description must include outgoing links on the described resource");
					assertTrue(described.filter(ALICE, RELATED, null)
							.stream()
							.anyMatch(statement -> statement.getObject() instanceof BNode),
							"the outgoing description must retain the blank-node object");
					assertTrue(described.contains(null, FOAF.NAME, Values.literal("child")),
							"the description must recursively expand a blank node object");
					assertTrue(described.contains(PARENT, RELATED, ALICE),
							"the description must include incoming links from another member");
				}
			}
		}
	}

